package com.example.bookstore;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

@SpringBootApplication  // includes @ComponentScan
public class BookstoreApplication {
    public static void main(String[] args) {
        SpringApplication.run(BookstoreApplication.class, args);
    }
}

// Service layer - automatically discovered
package com.example.bookstore.service;

import org.springframework.stereotype.Service;

@Service  // Spring finds this during component scan
public class BookService {
    public List<String> getAllBooks() {
        return List.of("Clean Code", "Effective Java");
    }
}

// Controller layer - automatically discovered
package com.example.bookstore.controller;

import org.springframework.web.bind.annotation.*;

@RestController  // specialized @Component
public class BookController {
    private final BookService bookService;

    // Spring injects BookService because both are scanned beans
    public BookController(BookService bookService) {
        this.bookService = bookService;
    }

    @GetMapping("/books")
    public List<String> getBooks() {
        return bookService.getAllBooks();
    }
}
