    }
}

// SCANNED: in sub-package of main class
package com.example.bookstore.service;

import org.springframework.stereotype.Service;

@Service
public class OrderService {}

// SCANNED: deeper nesting still under main package
package com.example.bookstore.config.security;

import org.springframework.context.annotation.Configuration;

@Configuration
public class SecurityConfig {}

// NOT SCANNED: sibling package to bookstore
package com.example.utils;

import org.springframework.stereotype.Component;

@Component  // Spring won't find this - outside scan root
public class DateFormatter {}

// NOT SCANNED: completely different root package
package com.other.library;

import org.springframework.stereotype.Service;

@Service  // Spring won't find this either
public class ExternalService {}
