package com.example.bookstore;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.ComponentScan;

// Approach 1: String-based package names
@SpringBootApplication
@ComponentScan(basePackages = {
    "com.example.bookstore",      // include default package
    "com.example.shared.utils",   // add shared utilities
    "com.thirdparty.integration"  // add external library
})
public class BookstoreApplication {
    public static void main(String[] args) {
        SpringApplication.run(BookstoreApplication.class, args);
    }
}

// Approach 2: Type-safe marker classes (preferred)
package com.example.shared.utils;
public interface UtilsPackageMarker {}  // marker in target package

package com.thirdparty.integration;
public interface IntegrationPackageMarker {}  // marker in external package

package com.example.bookstore;

@SpringBootApplication
@ComponentScan(basePackageClasses = {
    BookstoreApplication.class,           // scan main package
    UtilsPackageMarker.class,             // scan utils package
    IntegrationPackageMarker.class        // scan integration package
})
public class BookstoreApplication {
    public static void main(String[] args) {
        SpringApplication.run(BookstoreApplication.class, args);
    }
}
