// Your own service class - use @Component
@Component
public class OrderService {
    private final OrderRepository repository;

    public OrderService(OrderRepository repository) {
        this.repository = repository;
    }

    public Order createOrder(String item) {
        return repository.save(new Order(item));
    }
}

// Third-party or complex setup - use @Bean
@Configuration
public class AppConfig {

    @Bean
    public ObjectMapper objectMapper() {
        var mapper = new ObjectMapper();
        mapper.configure(SerializationFeature.INDENT_OUTPUT, true);
        mapper.registerModule(new JavaTimeModule()); // custom configuration
        return mapper;
    }

    @Bean
    public RestTemplate restTemplate(RestTemplateBuilder builder) { // Spring injects builder
        return builder
            .setConnectTimeout(Duration.ofSeconds(5))
            .setReadTimeout(Duration.ofSeconds(10))
            .build();
    }
}
