import org.springframework.context.annotation.Scope;
import org.springframework.stereotype.Component;
import org.springframework.web.context.annotation.RequestScope;
import org.springframework.web.context.annotation.SessionScope;

// Default singleton scope - one instance shared across application
@Service
public class OrderService {
    public Order createOrder(String item) {
        return new Order(item);
    }
}

// Explicit singleton scope (same as default)
@Component
@Scope("singleton")
public class CacheManager {
    private final Map<String, Object> cache = new ConcurrentHashMap<>();
}

// Prototype scope - new instance every time
@Component
@Scope("prototype")
public class ReportGenerator {
    private LocalDateTime createdAt = LocalDateTime.now(); // unique per instance
}

// Request scope - one instance per HTTP request
@Component
@RequestScope
public class RequestContext {
    private String requestId = UUID.randomUUID().toString();
}

// Session scope - one instance per HTTP session
@Component
@SessionScope
public class UserSession {
    private String userId;
    private List<String> recentItems = new ArrayList<>();
}
