import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.stereotype.Service;

// Single bean of type OrderRepository - injection by type works
@Service
public class OrderService {
    private final OrderRepository orderRepository;

    // Constructor injection (preferred) - @Autowired optional on single constructor
    public OrderService(OrderRepository orderRepository) {
        this.orderRepository = orderRepository;
    }
}

// Multiple beans of same type - need @Qualifier to resolve
@Service
public class PaymentService {
    private final PaymentProcessor primaryProcessor;
    private final PaymentProcessor backupProcessor;

    public PaymentService(
        @Qualifier("stripePaymentProcessor") PaymentProcessor primaryProcessor,
        @Qualifier("paypalPaymentProcessor") PaymentProcessor backupProcessor
    ) {
        this.primaryProcessor = primaryProcessor;
        this.backupProcessor = backupProcessor;
    }
}

@Component("stripePaymentProcessor")  // explicit bean name
public class StripePaymentProcessor implements PaymentProcessor { }

@Component("paypalPaymentProcessor")
public class PaypalPaymentProcessor implements PaymentProcessor { }
